import React from 'react';
import Reveal from './Reveal';
import SectionHeading from './SectionHeading';
import Icon from './icons';
import { projects } from '../data/content';

const featured = projects.filter((p) => p.featured);

export default function Projects() {
  return (
    <section id="projects" className="py-16 px-6 border-t border-zinc-100">
      <div className="max-w-prose mx-auto">
        <Reveal>
          <SectionHeading eyebrow="Projects" heading="Cool stuff I've built" />
        </Reveal>

        <div className="mt-8 grid sm:grid-cols-2 gap-4">
          {featured.map((project, idx) => (
            <Reveal key={project.title} delay={idx * 50}>
              <div className="h-full rounded-2xl border border-zinc-100 bg-white p-5 shadow-sm hover:shadow-md hover:-translate-y-0.5 transition-all">
                <div className="w-9 h-9 rounded-lg bg-orange-50 flex items-center justify-center text-orange-500 mb-3">
                  <Icon name={project.icon} size={17} />
                </div>
                <h3 className="font-semibold text-zinc-900">{project.title}</h3>
                <p className="mt-1 text-sm text-orange-600">{project.tagline}</p>
                <p className="mt-2 text-sm text-zinc-500 leading-relaxed">{project.build}</p>
                <p className="mt-2 text-xs font-mono text-zinc-400">{project.tech.join(' · ')}</p>
              </div>
            </Reveal>
          ))}
        </div>
      </div>
    </section>
  );
}
